FROM posts p JOIN users au ON au.user_id = p.user_id
AND p.status = #{status}
AND (p.title LIKE CONCAT('%', #{searchString}, '%') OR p.content LIKE CONCAT('%', #{searchString}, '%') OR au.nickname LIKE CONCAT('%', #{searchString}, '%'))

FROM post_comments c JOIN users au ON au.user_id = c.user_id
AND c.status = #{status}
AND (c.content LIKE CONCAT('%', #{searchString}, '%') OR au.nickname LIKE CONCAT('%', #{searchString}, '%'))

FROM book_reviews br JOIN users au ON au.user_id = br.user_id
AND br.status = #{status}
AND (br.content LIKE CONCAT('%', #{searchString}, '%') OR au.nickname LIKE CONCAT('%', #{searchString}, '%'))

mapper.update:
UPDATE reports
SET status = 'RESOLVED',
    handler_user_id = #{handlerUserId},
    processed_at = #{processedAt},
    updated_at = #{processedAt}
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND status IN ('PENDING', 'REVIEWING')
